"use client";

import { Button } from '@mantine/core';

import { useClipboard } from '@mantine/hooks';

function Demo() {
  const clipboard = useClipboard({ timeout: 500 });

  return (
    <Button
      color={clipboard.copied ? 'teal' : 'blue'}
      onClick={() => clipboard.copy('Hello, world!')}
    >
      {clipboard.copied ? 'Copied' : 'Copy'}
    </Button>
  );
}
const RendynExampleComponent = Demo;
export function RendynExample() { return <RendynExampleComponent  />; }

"use client";

import { RendynExample as Example } from "@/components/rendyn-libraries/mantine/upstream/src/demos/hooks/use-clipboard/use-clipboard.usage.demo";
import { MantineProvider } from "@mantine/core";
import "@mantine/core/styles.css";

export default function Preview() {

  return <div style={{ width: "100%", maxWidth: "48rem", padding: "1.5rem" }}><MantineProvider><Example /></MantineProvider></div>;
}
